{{ config(
            materialized='table',
                post_hook={
                    "sql": "Create Or Replace table DATALAKE_DB.kaya.dwh_Availability_Report as WITH SKU_Master as ( select distinct lower(marketplace_sku) marketplace_sku from ( select distinct marketplace_sku from datalake_db.kaya.Final_SKU_master union all select distinct parent from datalake_db.kaya.Final_SKU_master union all select distinct pid from datalake_db.kaya.Final_SKU_master union all select distinct old_sku from datalake_db.kaya.Final_SKU_master union all select distinct marico_code from datalake_db.kaya.Final_SKU_master ) ), base_data AS ( SELECT Upper(CASE WHEN channel_id = 1 THEN \'amazon\' WHEN channel_id = 2 THEN \'flipkart\' WHEN channel_id = 25 THEN \'nykaa\' WHEN channel_id = 27 THEN \'blinkit\' WHEN channel_id = 28 THEN \'myntra\' WHEN channel_id = 39 THEN \'flipkart grocery\' WHEN channel_id = 65 THEN \'swiggy\' WHEN channel_id = 109 THEN \'zepto\' WHEN channel_id = 160 THEN \'tira\' WHEN channel_id = 181 THEN \'google_ads\' WHEN channel_id = 183 THEN \'facebook_ads\' WHEN channel_id = 194 THEN \'youtube\' WHEN channel_id = 198 THEN \'google_dv360_ads\' ELSE \'other\' END) AS channel, CAST(CRAWL_DATE AS DATE) AS date, trim(upper(sku)) as SKU, MAX(IFNULL(price, 0)) AS price, MAX(case when lower(AVAILABILITY_STATUS) = \'pna\' then \'unavailable\' else AVAILABILITY_STATUS end ) AS availability FROM dev_db_shr.VENDOR.TRN_MARICO_BRANDED_QCOMM_AVAILABILITY WHERE LOWER(brand) = \'kaya\' and lower(trim((sku))) in (select distinct trim(lower(marketplace_sku)) from SKU_Master) GROUP BY 1, 2, 3 ) , Sales_base_data AS ( SELECT CAST(Date AS DATE) AS Date, trim(UPPER(split(ASIN,\'.\')[0])) AS ASIN, trim(upper(platform_name)) AS channel, SUM(IFNULL(shipped_unit, 0)) AS shipped_unit, sum(ifnull(indexbpm,0)) as INDEXBPM FROM PRD_DB_SHR.PUBLIC.DWH_IND_ECOMM_OFFTAKE_DAILY WHERE UPPER(material_group_code) IN (\'KAYA_GM\', \'KAYA_ML\') GROUP BY 1, 2, 3 ), Combine_Result as ( Select a.*, s.shipped_unit, s.INDEXBPM, s.date as SALES_DATE from base_data a left join Sales_base_data S on a.Date = s.date and lower(a.sku) = lower(s.asin) and lower(a.channel) = lower(s.channel) ), Availability AS ( SELECT base.channel, base.date, base.SALES_DATE, base.sku, base.price, base.availability, base.shipped_unit, AVG(CASE WHEN b.date BETWEEN base.date - 6 AND base.date THEN IFNULL(b.price, 0) ELSE NULL END) AS avg_price_7d, COUNT(CASE WHEN LOWER(b.availability) = \'available\' AND b.date BETWEEN base.date - 6 AND base.date THEN 1 ELSE NULL END) / NULLIF(COUNT(CASE WHEN b.date BETWEEN base.date - 6 AND base.date THEN 1 ELSE NULL END), 0) AS availability_pct_7d, AVG(CASE WHEN b.date BETWEEN base.date - 14 AND base.date THEN IFNULL(b.price, 0) ELSE NULL END) AS avg_price_8_14d, COUNT(CASE WHEN LOWER(b.availability) = \'available\' AND b.date BETWEEN base.date - 14 AND base.date THEN 1 ELSE NULL END) / NULLIF(COUNT(CASE WHEN b.date BETWEEN base.date - 14 AND base.date THEN 1 ELSE NULL END), 0) AS availability_pct_8_14d, AVG(CASE WHEN b.date BETWEEN base.date - 21 AND base.date THEN IFNULL(b.price, 0) ELSE NULL END) AS avg_price_15_21d, COUNT(CASE WHEN LOWER(b.availability) = \'available\' AND b.date BETWEEN base.date - 21 AND base.date THEN 1 ELSE NULL END) / NULLIF(COUNT(CASE WHEN b.date BETWEEN base.date - 21 AND base.date THEN 1 ELSE NULL END), 0) AS availability_pct_15_21d, AVG(CASE WHEN b.date BETWEEN base.date - 28 AND base.date - 22 THEN IFNULL(b.price, 0) ELSE NULL END) AS avg_price_22_28d, COUNT(CASE WHEN LOWER(b.availability) = \'available\' AND b.date BETWEEN base.date - 28 AND base.date - 22 THEN 1 ELSE NULL END) / NULLIF(COUNT(CASE WHEN b.date BETWEEN base.date - 28 AND base.date - 22 THEN 1 ELSE NULL END), 0) AS availability_pct_22_28d, AVG(CASE WHEN b.date BETWEEN base.date - 29 AND base.date THEN IFNULL(b.price, 0) ELSE NULL END) AS avg_price_30d, COUNT(CASE WHEN LOWER(b.availability) = \'available\' AND b.date BETWEEN base.date - 29 AND base.date THEN 1 ELSE NULL END) / NULLIF(COUNT(CASE WHEN b.date BETWEEN base.date - 29 AND base.date THEN 1 ELSE NULL END), 0) AS availability_pct_30d, SUM(CASE WHEN b.Date BETWEEN base.Date - 6 AND base.Date THEN IFNULL(b.shipped_unit, 0) ELSE 0 END) AS shipped_unit_7d, SUM(CASE WHEN b.Date BETWEEN base.Date - 14 AND base.Date THEN IFNULL(b.shipped_unit, 0) ELSE 0 END) AS shipped_unit_8_14d, SUM(CASE WHEN b.Date BETWEEN base.Date - 21 AND base.Date THEN IFNULL(b.shipped_unit, 0) ELSE 0 END) AS shipped_unit_15_21d, SUM(CASE WHEN b.Date BETWEEN base.Date - 28 AND base.Date - 22 THEN IFNULL(b.shipped_unit, 0) ELSE 0 END) AS shipped_unit_22_28d, SUM(CASE WHEN b.Date BETWEEN base.Date - 29 AND base.Date THEN IFNULL(b.shipped_unit, 0) ELSE 0 END) AS shipped_unit_30d, SUM(CASE WHEN b.Date BETWEEN base.Date - 6 AND base.Date THEN IFNULL(b.INDEXBPM, 0) ELSE 0 END) AS INDEXBPM_7d, SUM(CASE WHEN b.Date BETWEEN base.Date - 14 AND base.Date THEN IFNULL(b.INDEXBPM, 0) ELSE 0 END) AS INDEXBPM_8_14d, SUM(CASE WHEN b.Date BETWEEN base.Date - 21 AND base.Date THEN IFNULL(b.INDEXBPM, 0) ELSE 0 END) AS INDEXBPM_15_21d, SUM(CASE WHEN b.Date BETWEEN base.Date - 28 AND base.Date - 22 THEN IFNULL(b.INDEXBPM, 0) ELSE 0 END) AS INDEXBPM_22_28d, SUM(CASE WHEN b.Date BETWEEN base.Date - 29 AND base.Date THEN IFNULL(b.INDEXBPM, 0) ELSE 0 END) AS INDEXBPM_30d FROM Combine_Result base LEFT JOIN Combine_Result b ON b.channel = base.channel AND b.sku = base.sku AND b.date BETWEEN base.date - 29 AND base.date GROUP BY 1, 2, 3, 4, 5,6,7 ) SELECT a.*, GREATEST(0,div0(ifnull(INDEXBPM_7d,0) , ifnull(availability_pct_7d,0)) - (ifnull(INDEXBPM_7d,0))) Opportunity_Loss_7d, GREATEST(0,div0(IFNULL(INDEXBPM_8_14d, 0), IFNULL(availability_pct_8_14d, 0)) - IFNULL(INDEXBPM_8_14d, 0)) AS Opportunity_Loss_14d, GREATEST(0,div0(IFNULL(INDEXBPM_15_21d, 0), IFNULL(availability_pct_15_21d, 0)) - IFNULL(INDEXBPM_15_21d, 0)) AS Opportunity_Loss_21d, coalesce(fsm.product_title,fsm1.product_title) product_title, coalesce(fsm.sub_category,fsm1.sub_category) sub_category from Availability a left join ( select * from datalake_db.kaya.Final_SKU_master qualify row_number() over(partition by trim(upper(marketplace_SKU)) order by 1) = 1 )fsm on trim(upper(a.sku)) = trim(upper(fsm.marketplace_SKU)) left join ( select * from datalake_db.kaya.Final_SKU_master qualify row_number() over(partition by trim(upper(pid)) order by 1) = 1 )fsm1 on trim(upper(a.sku)) = trim(upper(fsm1.pid)) where a.date >= \'2025-01-01\' ; Create or Replace table datalake_db.kaya.kaya_inventyory_Fact_items as With inventory_base_Data as ( SELECT TO_DATE(_AIRBYTE_DATA:\"Date\"::STRING, \'DD-MM-YYYY\') AS stock_date, _AIRBYTE_DATA:\"Chain\"::STRING AS retail_chain, _AIRBYTE_DATA:\"FSN\"::STRING AS fsn_code, _AIRBYTE_DATA:\"SOH\"::int AS stock_on_hand, _AIRBYTE_DATA:\"material_code\"::STRING AS material_code, _AIRBYTE_DATA:\"Desc\"::STRING AS product_description, _AIRBYTE_DATA:\"Brand\"::STRING AS brand_name, _AIRBYTE_DATA:\"UOM\"::STRING AS unit_of_measure, _AIRBYTE_DATA:\"vol per unit\"::STRING AS volume_per_unit, _AIRBYTE_DATA:\"Vol\"::STRING AS total_volume, _AIRBYTE_DATA:\"FY INDEX\"::STRING AS fiscal_year_index, _AIRBYTE_DATA:\"BPM in lacs\"::STRING AS bpm_in_lacs, _AIRBYTE_DATA:\"Category\"::STRING AS product_category, _AIRBYTE_DATA:\"eCOM Brands\"::STRING AS ecommerce_brand FROM datalake_db.kaya._airbyte_raw_trn_kaya_stock_on_hand qualify row_number() over(partition by stock_date,material_code order by 1) = 1 ), Final_inventory as ( select stock_date::date Date ,upper(trim(material_code)) material_code ,case when lower(retail_chain) like \'%amazon%\' then \'AMAZON\' else upper(retail_chain) end as retail_chain ,\'ECOM\' as Marketplace ,stock_on_hand from inventory_base_Data ), Sales_Data AS ( SELECT Date::DATE AS Date, upper(trim(material_code)) material_code, upper(PLATFORM_NAME) PLATFORM_NAME, \'ECOM\' as Marketplace, SUM(IFNULL(shipped_unit, 0)) AS shipped_unit FROM PRD_DB_SHR.PUBLIC.DWH_IND_ECOMM_OFFTAKE_DAILY WHERE UPPER(material_group_code) IN (\'KAYA_GM\', \'KAYA_ML\') GROUP BY 1, 2,3,4 ), final_result as ( select COALESCE(FI.Date, FS.Date)::date AS Date, FI.Date as Stock_Date, COALESCE(FI.material_code, FS.material_code) AS material_code, COALESCE(FI.Marketplace, FS.Marketplace) AS Marketplace, COALESCE(FI.retail_chain, FS.PLATFORM_NAME) AS PLATFORM_NAME, coalesce(p1.SUB_CATEGORY,p2.SUB_CATEGORY,p3.SUB_CATEGORY) as SubCategory, coalesce(p1.product_title,p2.product_title,p3.product_title) as ProductTitle, FI.stock_on_hand, FS.shipped_unit from Final_inventory FI full outer join Sales_Data FS on FI.Date = FS.Date and upper(FI.material_code) = upper(FS.material_code) and upper(FI.Marketplace) = upper(FS.Marketplace) and upper(FI.retail_chain) = upper(FS.PLATFORM_NAME) left join ( select * from datalake_db.kaya.Final_SKU_master qualify row_number() over(partition by trim(upper(marico_code)) order by 1) = 1 )p1 on trim(upper(COALESCE(FI.material_code, FS.material_code))) = upper(trim(p1.marico_code)) left join ( select * from datalake_db.kaya.Final_SKU_master qualify row_number() over(partition by trim(upper(parent)) order by 1) = 1 )p2 on trim(upper(COALESCE(FI.material_code, FS.material_code))) = upper(trim(p2.parent)) left join ( select * from datalake_db.kaya.Final_SKU_master qualify row_number() over(partition by trim(upper(old_sku)) order by 1) = 1 )p3 on trim(upper(COALESCE(FI.material_code, FS.material_code))) = upper(trim(p3.old_sku)) ) select A.Date, A.Stock_Date, A.material_code, A.Marketplace, A.PLATFORM_NAME, A.SubCategory, A.ProductTitle, A.stock_on_hand, A.shipped_unit, SUM(CASE WHEN b.date BETWEEN a.Date - 30 AND a.Date - 1 THEN b.shipped_unit ELSE 0 END) AS DRR_30_Days from final_result A left join final_result B ON a.material_code = b.material_code and a.Marketplace = b.Marketplace and a.PLATFORM_NAME = b.PLATFORM_NAME AND b.Date BETWEEN a.Date - 30 AND a.Date - 1 group by 1,2,3,4,5,6,7,8,9 ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

